import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { loginUser } from "../services/api";
import { Box, TextField, Button, Typography, Paper, InputAdornment } from "@mui/material";
import { makeStyles } from "@mui/styles";  // Now it will work
import { AccountCircle, LockIcon } from "@mui/icons-material";  // Now it will work

const useStyles = makeStyles((theme) => ({
    // Your styling here
}));

const Login = () => {
    const classes = useStyles();
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const { data } = await loginUser({ username, password });
            if (data.token) {
                localStorage.setItem("token", data.token);
                if (data.user.role === "superadmin") navigate("/superadmin");
                else if (data.user.role === "admin") navigate("/admin");
                else navigate("/user");
            } else {
                alert("Invalid Credentials");
            }
        } catch (error) {
            alert("Invalid Credentials");
        }
    };

    return (
        <Box className={classes.container}>
            <Paper className={classes.formContainer}>
                <Typography variant="h5" className={classes.title}>
                    Welcome Back
                </Typography>
                <form onSubmit={handleSubmit}>
                    <TextField
                        label="Username"
                        variant="outlined"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        fullWidth
                        className={classes.input}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <AccountCircle className={classes.icon} />
                                </InputAdornment>
                            ),
                        }}
                    />
                    <TextField
                        label="Password"
                        variant="outlined"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        fullWidth
                        className={classes.input}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <LockIcon className={classes.icon} />
                                </InputAdornment>
                            ),
                        }}
                    />
                    <Button
                        type="submit"
                        variant="contained"
                        fullWidth
                        className={classes.button}
                    >
                        Login
                    </Button>
                </form>
                <Typography className={classes.footerText}>
                    Don't have an account? <span style={{ fontWeight: 'bold' }}>Sign Up</span>
                </Typography>
            </Paper>
        </Box>
    );
};

export default Login;
